"""Runs the MCP server described by server.toml. Generated by `aaa mcp init`; edit the configuration, not this file."""

import asyncio
from pathlib import Path

from aaa.mcp import acompile_spec, load_spec, serve_stdio

CONFIG = Path(__file__).with_name("server.toml")


async def run() -> None:
    core = await acompile_spec(load_spec(CONFIG))
    if core.owns_engine and core.engine is not None:
        async with core.engine:
            await serve_stdio(core)
    else:
        await serve_stdio(core)


def main() -> None:
    asyncio.run(run())


if __name__ == "__main__":
    main()
